package com.pridesys.ticketing.repository; import com.pridesys.ticketing.dto.*; import com.pridesys.ticketing.entity.*; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class ModuleRecordRepository {private final ModuleRepository repo;public ModuleRecordRepository(ModuleRepository r){repo=r;}public List<ModuleRecord> findByProject(long p){return repo.findByProjectIdOrderByName(p).stream().map(this::record).toList();}public long create(long p,UsersProjectsDtos.CreateModuleRequest r){return repo.save(new ModuleEntity(p,r.name().trim(),r.description())).getId();}public void update(long id,UsersProjectsDtos.UpdateModuleRequest r){var e=repo.findById(id).orElseThrow();e.setName(r.name().trim());e.setDescription(r.description());if(r.active()!=null)e.setActive(r.active());repo.save(e);}public void delete(long id){repo.deleteById(id);}private ModuleRecord record(ModuleEntity e){return new ModuleRecord(e.getId(),e.getProjectId(),e.getName(),e.getDescription(),e.isActive());}}
